function allPicks(n: number, k: number): number[][] {
  const out: number[][] = [];
  for (let mask = 0; mask < 1 << n; mask++) {
    const pick: number[] = [];
    for (let b = 0; b < n; b++) if (mask & (1 << b)) pick.push(b + 1);
    if (pick.length === k) out.push(pick);
  }
  return out;
}

