function allPicks(n: number, k: number): number[][] {
  const out: number[][] = [];
  const path: number[] = [];
  const go = (start: number) => {
    if (path.length === k) { out.push([...path]); return; }
    const need = k - path.length;
    for (let v = start; v <= n - need + 1; v++) {
      path.push(v);
      go(v + 1);
      path.pop();
    }
  };
  go(1);
  return out;
}

